          "እያንዳንዱ ነባር አካል — ዓለማት፣ ነፍሳት፣ ሃሳቦች፣ ፍላጎቶች እና እንዲያውም አካላዊ አቶሞች — ልክ በዚህ የማይለወጥ የ 5 ደረጃዎች ንድፍ (0-4) የተገነቡ ስለሆኑ።",
